/* Rentcam public runtime v6 — scheduled products, labels, discounts, banners */
(function(){
  if(location.pathname.startsWith('/cms'))return;
  const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Math.max(0,Number(n)||0));
  function cfg(){return window.RENTCAM_CMS_CONFIG||null}
  function dayStart(s){return s?new Date(s+'T00:00:00').getTime():null}
  function dayEnd(s){return s?new Date(s+'T23:59:59').getTime():null}
  function inRange(a,b){const n=Date.now(),x=dayStart(a),y=dayEnd(b);return (!x||n>=x)&&(!y||n<=y)}
  function meta(id){const c=cfg();if(!c)return null;return (c.customProducts||[]).find(x=>String(x.id)===String(id))||(c.productOverrides||{})[id]||null}
  function productVisible(x){return !x||((x.active!==false)&&(x.deleted!==true)&&inRange(x.publishDate,x.unpublishDate))}
  function labelOn(x){return !!x?.labelText&&inRange(x.labelStart,x.labelEnd)}
  function discountOn(x){return Number(x?.discountPercent)>0&&inRange(x.discountStart,x.discountEnd)}
  function idFromCard(card){let id=card.getAttribute('data-product-id')||card.dataset?.productId||'';if(!id){const s=card.getAttribute('onclick')||'';const m=s.match(/\/produk\/([^'\")]+)/);if(m)id=m[1]}return decodeURIComponent(id||'')}
  function style(){if(document.getElementById('v6publicpromo'))return;const s=document.createElement('style');s.id='v6publicpromo';s.textContent=`.v6-product-label{position:absolute;z-index:5;left:10px;top:10px;background:#111;color:#fff;padding:7px 10px;border-radius:999px;font-size:10px;font-weight:900;letter-spacing:.04em}.v6-discount-label{background:#f26a21}.v6-old-price{text-decoration:line-through;color:#929292;font-weight:600;margin-right:6px}.v6-new-price{color:#d84d0f;font-weight:900}.v6-detail-promo{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 14px}.v6-detail-promo span{display:inline-flex;padding:7px 10px;border-radius:999px;font-size:11px;font-weight:900;background:#111;color:#fff}.v6-detail-promo span.sale{background:#f26a21}.v6-hero-label{display:inline-flex;margin-bottom:10px;padding:7px 10px;border-radius:999px;background:#f26a21;color:#fff;font-size:10px;font-weight:900;letter-spacing:.06em}@media(max-width:620px){.v6-product-label{font-size:8px;padding:6px 8px;left:7px;top:7px}}`;document.head.appendChild(s)}
  function parsePrice(el){const t=el?.textContent||'';const m=t.replace(/\./g,'').replace(/,/g,'').match(/(?:Rp\s*)?(\d{2,})/i);return m?Number(m[1]):0}
  function patchCard(card){const id=idFromCard(card);if(!id)return;const x=meta(id);if(!x)return;card.style.display=productVisible(x)?'':'none';if(!productVisible(x))return;const holder=card.querySelector('.pimg,.home-category-image')||card;holder.style.position='relative';let lab=holder.querySelector('.v6-product-label');if(labelOn(x)||discountOn(x)){if(!lab){lab=document.createElement('span');lab.className='v6-product-label';holder.appendChild(lab)}const txt=labelOn(x)?x.labelText:(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%'));lab.textContent=txt;lab.className='v6-product-label'+(discountOn(x)?' v6-discount-label':'')}else lab?.remove();const pr=card.querySelector('.price');if(pr){if(!pr.dataset.v6Original)pr.dataset.v6Original=pr.innerHTML;if(discountOn(x)){const base=Number(x.price)||Number(pr.dataset.v6Base)||parsePrice(pr);if(base){pr.dataset.v6Base=base;const cut=Math.round(base*(1-Number(x.discountPercent)/100));pr.innerHTML=`<span class="v6-old-price">${money(base)}</span><span class="v6-new-price">${money(cut)}</span> <small>/ full day</small>`}}else if(pr.dataset.v6Original)pr.innerHTML=pr.dataset.v6Original}}
  function patchCards(){document.querySelectorAll('#app .pcard,#app [data-product-id],#app .home-category-card').forEach(patchCard)}
  function currentProductId(){const m=location.pathname.match(/^\/produk\/([^/?#]+)/);return m?decodeURIComponent(m[1]):''}
  function patchDetail(){const id=currentProductId();if(!id)return;const x=meta(id);if(!x)return;const app=document.getElementById('app');if(!productVisible(x)){const root=app?.querySelector('.page')||app;if(root)root.innerHTML='<div class="container" style="padding:80px 0"><h1>Produk tidak tersedia</h1><p>Produk ini sedang dinonaktifkan atau berada di luar jadwal tampil.</p><button class="btn" onclick="go(\'/produk\')">Kembali ke Rentals</button></div>';return}const h1=app?.querySelector('h1');if(h1){let box=h1.parentElement?.querySelector('.v6-detail-promo');if(!box){box=document.createElement('div');box.className='v6-detail-promo';h1.insertAdjacentElement('afterend',box)}box.innerHTML='';if(labelOn(x))box.insertAdjacentHTML('beforeend',`<span>${String(x.labelText).replace(/</g,'&lt;')}</span>`);if(discountOn(x))box.insertAdjacentHTML('beforeend',`<span class="sale">${String(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%')).replace(/</g,'&lt;')}</span>`);if(!box.childElementCount)box.remove()}const pr=app?.querySelector('.price');if(pr){if(!pr.dataset.v6Original)pr.dataset.v6Original=pr.innerHTML;if(discountOn(x)){const base=Number(x.price)||parsePrice(pr);if(base){const cut=Math.round(base*(1-Number(x.discountPercent)/100));pr.innerHTML=`<span class="v6-old-price">${money(base)}</span><span class="v6-new-price">${money(cut)}</span> <small>/ full day</small>`}}}}
  function bannerValid(x){return x?.active!==false&&x?.deleted!==true&&inRange(x?.startDate,x?.endDate)}
  function patchHero(){const c=cfg(),hero=document.querySelector('#app .hero');if(!c||!hero||!(c.banners||[]).length)return;const valid=(c.banners||[]).filter(bannerValid);if(!valid.length){hero.style.display='none';return}hero.style.display='';const title=hero.querySelector('h1')?.textContent?.trim()||'',cur=(c.banners||[]).find(x=>(x.title||'').trim()===title);const b=cur&&bannerValid(cur)?cur:valid[0];if(!b)return;const h=hero.querySelector('h1'),p=hero.querySelector('p'),small=hero.querySelector('small');if(h&&b.title)h.textContent=b.title;if(p&&(b.text||b.subtitle))p.textContent=b.text||b.subtitle;if(small&&(b.ey||b.kicker))small.textContent=b.ey||b.kicker;if(b.image)hero.style.backgroundImage=`url('${b.image}')`;let lab=hero.querySelector('.v6-hero-label');const txt=b.promoLabel||(Number(b.discountPercent)>0?('PROMO '+Number(b.discountPercent)+'%'):'');if(txt){if(!lab){lab=document.createElement('span');lab.className='v6-hero-label';const con=hero.querySelector('.container');con?.prepend(lab)}lab.textContent=txt}else lab?.remove()}
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;style();patchCards();patchDetail();patchHero()})}
  document.addEventListener('rentcam-cms-updated',run);new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});addEventListener('popstate',run);style();setTimeout(run,350);setTimeout(run,1200);
})();